with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('ændre kurs', 'phrase', '48778e84-e7f1-5029-8737-dd58a87ad3bf', 1, 'verb', null, 'змінювати курс', 'Skibet ændrede kurs for at undgå stormen.', 'Корабель змінив курс, щоб уникнути бурі.'), ('elske med', 'phrase', 'f658a3df-5554-5ee2-945f-78b1de15cbc1', 1, 'verb', null, 'займатися коханням', 'De elskede med hinanden hele natten.', 'Вони кохалися одне з одним всю ніч.'), ('brede sig', 'phrase', '88f17d8c-9b5a-59ac-a6dd-65badb00cdc5', 1, 'verb', null, 'поширюватися', 'Nyheden bredte sig hurtigt i byen.', 'Новина швидко поширилася містом.'), ('brede sig', 'phrase', '9ac47aac-4379-5467-9ec6-dcfd4984a030', 2, 'verb', null, 'простягатися (про краєвид)', 'Sletten breder sig foran os.', 'Рівнина простягається перед нами.'), ('komme i tanke om', 'phrase', '5999d985-92db-525f-8b72-9a7e9b5ff768', 1, 'verb', null, 'згадувати (раптово)', 'Jeg kom i tanke om, at jeg havde glemt mine nøgler.', 'Я згадав, що забув ключі.'), ('komme i tanker om', 'phrase', '74b19243-d89d-528f-9cfb-15ef81e76c8d', 1, 'verb', null, 'згадувати (раптово)', 'Jeg kom i tanker om, at jeg havde glemt min nøgle.', 'Я згадав, що забув свій ключ.'), ('være forkert på den', 'phrase', '9db81698-d278-5449-acb4-5156b5b3a770', 1, 'verb', null, 'помилятися', 'Du er forkert på den, hvis du tror, jeg kommer i morgen.', 'Ти помиляєшся, якщо думаєш, що я прийду завтра.'), ('ringe sammen', 'phrase', '9edff16d-5c03-5a8b-be7a-e3f3f799ec17', 1, 'verb', null, 'телефонувати одне одному', 'Vi ringer sammen hver aften inden sengetid.', 'Ми телефонуємо одне одному щовечора перед сном.'), ('skære ned', 'phrase', '667973c5-7042-564a-8023-0006252c9a1a', 1, 'verb', null, 'скорочувати (витрати, штат)', 'Virksomheden skar ned på udgifterne sidste år.', 'Минулого року компанія скоротила витрати.'), ('blive mand og kone', 'phrase', 'e033dd7a-07c1-597d-b0ea-9331f0748d43', 1, 'verb', null, 'одружитися (стати чоловіком і дружиною)', 'De blev mand og kone i en lille kirke sidste sommer.', 'Минулого літа вони стали чоловіком і дружиною в маленькій церкві.'), ('der er pres på', 'phrase', 'c2c2eb9b-c976-5b4f-bd7a-37efa4c0c4b9', 1, 'phrase', null, 'напружена ситуація, цейтнот', 'Der er pres på i køkkenet lige før gæsterne kommer.', 'На кухні напружена ситуація перед самим приходом гостей.'), ('gøre tegn', 'phrase', 'c5e3de84-4eee-556e-a501-b649133f1d86', 1, 'verb', null, 'подавати знак', 'Hun gjorde tegn til tjeneren, at hun ville betale.', 'Вона жестом показала офіціанту, що хоче заплатити.'), ('gøre tegn til', 'phrase', '057264db-09c4-5a84-9d6b-d5e4f2f24279', 1, 'verb', null, 'подавати знак (щоб щось зробити)', 'Han gjorde tegn til, at vi skulle følge med.', 'Він жестом показав, щоб ми йшли за ним.'), ('tegne til', 'phrase', '5e638664-986b-507c-9a7c-b6d37049d2b2', 1, 'verb', null, 'виглядати (здаватися)', 'Det tegner til at blive en god dag.', 'Схоже, буде гарний день.'), ('holde sig varm', 'phrase', '14df8ba7-96dc-569c-b425-791d7aa977fb', 1, 'verb', null, 'зігріватися (не мерзнути)', 'Jeg tager en ekstra trøje på for at holde mig varm.', 'Я одягаю додатковий светр, щоб зігрітися.'), ('gå til angreb', 'phrase', 'ed3c37a4-c078-5f62-8a41-655b03cabb22', 1, 'verb', null, 'атакувати (почати атаку)', 'Soldaterne gik til angreb ved daggry.', 'Солдати атакували на світанку.'), ('være galt på den', 'phrase', '3fe1ea1c-8742-5626-90c1-d295f60f2733', 1, 'verb', null, 'помилятися, бути неправим', 'Jeg tror, du er galt på den med den information.', 'Я думаю, ти помиляєшся щодо цієї інформації.'), ('tale forbi hinanden', 'phrase', '77537748-abb6-5a4f-8faa-6ce33aed3c74', 1, 'verb', null, 'говорити про різне, не розуміючи одне одного', 'Vi talte forbi hinanden hele aftenen og blev uvenner.', 'Ми весь вечір говорили на різних мовах і посварилися.'), ('gribe ind', 'phrase', '9e2b776e-5a3a-590e-9ea7-c1b15aef74e5', 1, 'verb', null, 'втручатися', 'Politiet måtte gribe ind, da demonstrationen blev voldelig.', 'Поліції довелося втрутитися, коли демонстрація переросла в насильство.'), ('få styr på', 'phrase', 'eae2c396-c9a0-58ab-8ed4-29e5badf9b90', 1, 'verb', null, 'навести лад (розібратися)', 'Hun fik styr på sine papirer inden mødet.', 'Вона впорядкувала свої документи перед зустріччю.'), ('være i bevægelse', 'phrase', 'bcd2194d-ad36-54af-90f3-6bb97b5a7bc3', 1, 'verb', null, 'рухатися', 'Bilen er i bevægelse, selv om den kører langsomt.', 'Автомобіль рухається, хоч і повільно.'), ('gøre opmærksom på', 'phrase', '98b60b3e-db37-5d21-8a45-588d18034b3c', 1, 'verb', null, 'звертати увагу (на щось)', 'Læreren gjorde opmærksom på fejlen i teksten.', 'Учитель вказав на помилку в тексті.'), ('stå ansigt til ansigt', 'phrase', '9e9cc310-5e7c-563a-9c72-a3122a8c1cbe', 1, 'verb', null, 'стояти обличчям до обличчя', 'De stod ansigt til ansigt i den lille elevator.', 'Вони стояли обличчям до обличчя в маленькому ліфті.'), ('kunne bunde', 'phrase', '0ec53350-f771-5c44-9f6a-ba3f6e49fbc7', 1, 'verb', null, 'діставати до дна (у воді)', 'Han kan bunde i den lave ende af poolen.', 'Він може дістати до дна на мілководді басейну.'), ('gifte sig ind i', 'phrase', 'd0964726-5094-5360-b20c-8db51c23202f', 1, 'verb', null, 'породичатися з (родиною) через шлюб', 'Han giftede sig ind i en rig familie.', 'Він породичався із заможною родиною.'), ('skaffe sig af med', 'phrase', '95e5ddb1-5d10-568f-85e0-26d07db34358', 1, 'verb', null, 'позбуватися (чогось)', 'Hun vil gerne skaffe sig af med sin gamle cykel.', 'Вона хоче позбутися свого старого велосипеда.'), ('sidde oppe', 'phrase', '4e204935-bca4-59c8-b5f7-15caac9ffad3', 1, 'verb', null, 'не лягати спати', 'Børnene sad oppe til midnat i går.', 'Вчора діти не лягали спати до півночі.'), ('første skridt', 'phrase', 'd0bbdf7b-7291-501d-b785-c4bef37fdb12', 1, 'phrase', null, 'перший крок (у процесі)', 'At spare penge er det første skridt mod en bedre økonomi.', 'Заощадження грошей — це перший крок до кращої економіки.'), ('have fat i', 'phrase', '04ac4a3e-8c42-58e7-8c4c-4ec0de3a05fb', 1, 'verb', null, 'тримати, схопити', 'Jeg har fat i din taske.', 'Я тримаю твою сумку.'), ('flyve ind', 'phrase', '17745ce7-6f3d-5d3b-9c8b-a68759d43a4f', 1, 'verb', null, 'влітати (всередину)', 'Fuglen fløj ind ad vinduet.', 'Птах влетів у вікно.'), ('løbe med snak', 'phrase', '7550700e-600c-59ac-a99b-40dfeee3a1fa', 1, 'verb', null, 'захоплюватися розмовою (забуваючи про час)', 'Vi løb med snak og glemte helt aftensmaden.', 'Ми захопилися розмовою і зовсім забули про вечерю.'), ('føre en samtale', 'phrase', '45d024c5-d299-5088-aa37-7c403126ec85', 1, 'verb', null, 'вести розмову', 'De fører en samtale om vejret.', 'Вони розмовляють про погоду.'), ('tage tøj på', 'phrase', '0cdb9233-eed1-5bd4-8c78-c95c29cd278e', 1, 'verb', null, 'одягатися', 'Jeg tager tøj på, inden jeg går ud.', 'Я одягаюся перед тим, як вийти.'), ('investere i', 'phrase', '6a76f49c-00f6-537d-99c7-2aed9404a89d', 1, 'verb', null, 'вкладати (гроші) в', 'Mange vælger at investere i aktier.', 'Багато людей обирають інвестувати в акції.'), ('drikke op', 'phrase', '34c3f377-4343-5569-8222-fd0ab0d8341e', 1, 'verb', null, 'допивати', 'Han drak op og gik hjem.', 'Він допив і пішов додому.'), ('drikke sig fuld', 'phrase', 'b47cefa0-c328-52b2-95c1-352696ea7b9a', 1, 'verb', null, 'напиватися (доп''яну)', 'Han drikker sig fuld hver fredag.', 'Він напивається щоп''ятниці.'), ('drikke tæt', 'phrase', 'ec4dc882-6fd8-5cfc-93fb-3f716597ccdf', 1, 'verb', null, 'пити багато (алкоголь)', 'Han drak tæt hele weekenden.', 'Він багато пив весь вікенд.'), ('brænde sig på', 'phrase', '5e1be1ab-76a3-56d8-9a4e-f67f9239a6ee', 1, 'verb', null, 'обпектися (отримати опік)', 'Pas på du ikke brænder dig på den varme pande.', 'Дивись не обпечися об гарячу сковороду.'), ('brænde sig på', 'phrase', '129ed172-dab3-53db-8c0f-4151d2121cf0', 2, 'verb', null, 'обпектися (зазнати невдачі через щось)', 'Mange investorer brændte sig på aktiemarkedet sidste år.', 'Багато інвесторів обпеклися на фондовому ринку минулого року.'), ('brænde ud', 'phrase', 'e479c414-76b1-5cb9-b84d-44751d48355f', 1, 'verb', null, 'вигоряти (емоційно)', 'Jeg brænder ud, hvis jeg arbejder for meget.', 'Я вигораю, якщо занадто багато працюю.'), ('tyde på', 'phrase', 'c341b3d2-946e-590d-bfb0-be1e35b67665', 1, 'verb', null, 'вказувати на (щось)', 'De mørke skyer tyder på regn.', 'Темні хмари вказують на дощ.'), ('løfte op i', 'phrase', '5ac1a4c1-c959-50df-ad8a-52790c2bd7f1', 1, 'verb', null, 'піднімати (щось) трохи', 'Hun løftede op i låget for at kigge ned i gryden.', 'Вона трохи підняла кришку, щоб заглянути в каструлю.'), ('løfte sig', 'phrase', '64b7c721-25aa-54d2-bf2d-bb8735b2759d', 1, 'verb', null, 'підніматися (про туман, завісу)', 'Tågen løftede sig langsomt over marken.', 'Туман повільно піднімався над полем.'), ('meddele sig', 'phrase', '98996bd4-686b-5683-b2c4-ad52c37c6951', 1, 'verb', null, 'проявлятися, даватися взнаки (про почуття, біль)', 'Trætheden begyndte at meddele sig efter den lange gåtur.', 'Втома почала проявлятися після довгої прогулянки.'), ('være undervejs', 'phrase', '0904a524-8bf9-50d3-a56f-21b863256db4', 1, 'verb', null, 'бути в дорозі', 'Pakken er undervejs og kommer i morgen.', 'Посилка вже в дорозі і прибуде завтра.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'uk'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'uk', text, pos, gender, example, example_translation, 'pipeline-phrases-0014' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
